/**
 * Background Sync bridge.
 *
 * The service worker (generated by vite-plugin-pwa / Workbox) registers a
 * Background Sync queue for Supabase REST mutations. When a write fails while
 * offline, the browser retries it in the background — even if the app/tab is
 * closed — as soon as connectivity returns.
 *
 * The in-app IndexedDB outbox is kept as a shadow fallback: entries handed to
 * the service worker are only replayed by the app if the service worker has
 * clearly failed to deliver them (see SHADOW_REPLAY_AFTER_MS in sync.ts).
 */
export function isBackgroundSyncAvailable(): boolean {
  return (
    typeof window !== "undefined" &&
    "serviceWorker" in navigator &&
    "SyncManager" in window &&
    !!navigator.serviceWorker.controller
  );
}
